const tabId = 730410078;
const content = await browserjs(tabId, () => {
  const sections = [];
  const h2s = Array.from(document.querySelectorAll('h2'));
  for (const h2 of h2s) {
    const title = h2.textContent.trim();
    if (/^\d+\./.test(title)) {
      let text = '';
      let curr = h2.nextElementSibling;
      while (curr && curr.tagName !== 'H2') {
        text += curr.textContent.trim() + '\n';
        curr = curr.nextElementSibling;
      }
      sections.push({ title, text });
    }
  }
  return sections;
});
console.log(content.map(s => `${s.title}:\n${s.text.slice(0, 300)}...\n`).join('\n---\n'));

