const tabId = 730410078;
const texts = await browserjs(tabId, () => {
  const titles = [
    "12. Roasted chickpeas",
    "13. Baked tofu",
    "24. Edamame",
    "26. Quinoa",
    "27. Lentil salad",
    "30. “Cheesy” seasoned popcorn"
  ];
  const h2s = Array.from(document.querySelectorAll('h2'));
  const results = {};
  for (const h2 of h2s) {
    const text = h2.textContent.trim();
    for (const t of titles) {
      if (text.includes(t)) {
        // Find next elements until next h2
        let parent = h2.parentElement;
        // let's climb until we find sibling elements
        while (parent && !parent.nextElementSibling && parent.parentElement && parent.parentElement.tagName !== 'BODY') {
          parent = parent.parentElement;
        }
        let collected = '';
        let sibling = parent ? parent.nextElementSibling : null;
        while (sibling) {
          if (sibling.querySelector('h2') || sibling.tagName === 'H2') break;
          collected += sibling.textContent.trim() + '\n';
          sibling = sibling.nextElementSibling;
        }
        results[t] = collected;
      }
    }
  }
  return results;
});
console.log(JSON.stringify(texts, null, 2));

