const tabId = 730410078;
await tool.navigate({ tabId, url: "https://www.healthline.com/nutrition/edamame-benefits" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
const prepSection = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3'));
  for (const h of headings) {
    if (h.textContent.toLowerCase().includes('cook') || h.textContent.toLowerCase().includes('prepare') || h.textContent.toLowerCase().includes('eat')) {
      let text = h.textContent + '\n';
      let curr = h.parentElement;
      while (curr && !curr.nextElementSibling && curr.parentElement && curr.parentElement.tagName !== 'BODY') {
        curr = curr.parentElement;
      }
      let sib = curr ? curr.nextElementSibling : null;
      while (sib && !sib.querySelector('h2')) {
        text += sib.textContent + '\n';
        sib = sib.nextElementSibling;
      }
      return text;
    }
  }
  return 'Not found';
});
console.log(prepSection);

