const tabId = 730410078;
const items = await browserjs(tabId, () => {
  const titles = ["5. Edamame", "16. Herbed popcorn"];
  const res = {};
  const h2s = Array.from(document.querySelectorAll('h2, h3'));
  for (const h of h2s) {
    const text = h.textContent.trim();
    for (const t of titles) {
      if (text.includes(t)) {
        let parent = h.parentElement;
        while (parent && !parent.nextElementSibling && parent.parentElement && parent.parentElement.tagName !== 'BODY') {
          parent = parent.parentElement;
        }
        let collected = '';
        let sibling = parent ? parent.nextElementSibling : null;
        while (sibling) {
          if (sibling.querySelector('h2, h3') || sibling.tagName === 'H2' || sibling.tagName === 'H3') break;
          collected += sibling.textContent.trim() + '\n';
          sibling = sibling.nextElementSibling;
        }
        res[t] = collected;
      }
    }
  }
  return res;
});
console.log(JSON.stringify(items, null, 2));

